   327→// ---------------------------------------------------------------------------
   328→// File / PDF extraction
   329→// ---------------------------------------------------------------------------
   330→
   331→// Keywords in link text / aria-label that strongly hint at a downloadable file
   332→const DOWNLOAD_HINT_RE =
   333→  /\b(pdf|download|report|whitepaper|white\s*paper|brochure|guide|ebook|e-book|spec|datasheet|data\s*sheet|form|application|invoice|receipt|manual|handbook|press\s*kit|media\s*kit|catalog|catalogue)\b/i;
   334→
   335→function extractFiles($, baseUrl) {
   336→  const files = [];
   337→
   338→  function push(url, text, ext) {
   339→    const abs = safeAbsolute(url, baseUrl);
   340→    if (!abs) return;
   341→    const resolvedExt = ext || getExtension(abs);
   342→    files.push({
   343→      url: abs,
   344→      text: (text || "").trim().replace(/\s+/g, " ") || fileName(abs),
   345→      type: resolvedExt.toUpperCase() || "FILE",
   346→      ext: resolvedExt,
   347→    });
   348→  }
   349→
   350→  // 1. <a href> — URL ends in a known extension
   351→  $("a[href]").each((_, el) => {
   352→    const href = $(el).attr("href");
   353→    if (!href) return;
   354→    const ext = getExtension(href);
   355→    if (DOWNLOADABLE_EXTENSIONS.has(ext)) {
   356→      push(href, $(el).text(), ext);
   357→    }
   358→  });
   359→
   360→  // 2. <a href> — URL doesn't end in .pdf but link text / attributes hint at it
   361→  $("a[href]").each((_, el) => {
   362→    const href = $(el).attr("href");
   363→    if (!href) return;
   364→    const ext = getExtension(href);
   365→    if (DOWNLOADABLE_EXTENSIONS.has(ext)) return; // already captured above
   366→
   367→    const text   = $(el).text().trim();
   368→    const label  = $(el).attr("aria-label") || "";
   369→    const title  = $(el).attr("title") || "";
   370→    const dlAttr = $(el).attr("download");
   371→
   372→    const isPdfHint =
   373→      DOWNLOAD_HINT_RE.test(text) ||
   374→      DOWNLOAD_HINT_RE.test(label) ||
   375→      DOWNLOAD_HINT_RE.test(title) ||
   376→      dlAttr !== undefined ||                      // has download= attribute
   377→      /\.(pdf|docx?|xlsx?|pptx?)(\?|$)/i.test(href); // extension in query string
   378→
   379→    if (isPdfHint) {
   380→      // Guess type from URL path or hint keywords
   381→      const guessedExt =
   382→        /pdf/i.test(href + text + label) ? "pdf" :
   383→        /doc/i.test(href + text + label) ? "docx" :
   384→        /xls/i.test(href + text + label) ? "xlsx" : "";
   385→      push(href, text || label || title, guessedExt);
   386→    }
   387→  });
   388→
   389→  // 3. <iframe src>, <embed src>, <object data> — often used for inline PDFs
   390→  $("iframe[src], embed[src], object[data]").each((_, el) => {
   391→    const src = $(el).attr("src") || $(el).attr("data");
   392→    if (!src) return;
   393→    const ext = getExtension(src);
   394→    if (ext === "pdf" || DOWNLOADABLE_EXTENSIONS.has(ext)) {
   395→      const title = $(el).attr("title") || $(el).attr("name") || "";
   396→      push(src, title, ext || "pdf");
   397→    }
   398→  });
   399→
   400→  // 4. Inline <script> / data attributes — some React/Next sites embed file
   401→  //    URLs as JSON in data-* props (e.g. data-file-url, data-pdf-url)
   402→  $("[data-pdf-url], [data-file-url], [data-download-url], [data-href]").each((_, el) => {
   403→    const url =
   404→      $(el).attr("data-pdf-url") ||
   405→      $(el).attr("data-file-url") ||
   406→      $(el).attr("data-download-url") ||
   407→      $(el).attr("data-href");
   408→    if (url) {
   409→      const ext = getExtension(url);
   410→      push(url, $(el).text().trim(), ext || "pdf");
   411→    }
   412→  });
   413→
   414→  return dedupeBy(files, "url");
   415→}
   416→
   417→function fileName(url) {
   418→  try {
   419→    return decodeURIComponent(new URL(url).pathname.split("/").pop()) || url;
   420→  } catch {
   421→    return url;
   422→  }
   423→}
   424→
   425→// ---------------------------------------------------------------------------
   426→// Link extraction
   427→// ---------------------------------------------------------------------------
   428→
   429→function extractLinks($, baseUrl) {
   430→  const base = new URL(baseUrl);
   431→  const internal = [];
   432→  const external = [];
   433→
   434→  $("a[href]").each((_, el) => {
   435→    const href = $(el).attr("href");
   436→    if (!href || href.startsWith("mailto:") || href.startsWith("tel:") || href === "#")
   437→      return;
   438→
   439→    const abs = safeAbsolute(href, baseUrl);
   440→    if (!abs) return;
   441→
   442→    const parsed = new URL(abs);
   443→    const text = $(el).text().trim().replace(/\s+/g, " ").slice(0, 80);
   444→    const link = { href: abs.split("#")[0], text };
   445→
   446→    if (parsed.hostname === base.hostname) internal.push(link);
   447→    else external.push(link);
   448→  });
   449→
   450→  return {
   451→    internal: dedupeBy(internal, "href"),
   452→    external: dedupeBy(external, "href"),
   453→  };
   454→}
   455→
   456→// ---------------------------------------------------------------------------
   457→// Headings extraction
   458→// ---------------------------------------------------------------------------
   459→
   460→function extractHeadings($) {
   461→  const headings = [];
   462→  ["h1", "h2", "h3", "h4"].forEach((tag) => {
   463→    $(tag).each((_, el) => {
   464→      const text = $(el).text().trim().replace(/\s+/g, " ");
   465→      if (text) headings.push({ level: tag, text });
   466→    });
   467→  });
   468→  return headings;
   469→}
   470→
   471→// ---------------------------------------------------------------------------
   472→// Product / pricing block extraction
   473→// ---------------------------------------------------------------------------
   474→
   475→function extractProductBlocks($, baseUrl) {
   476→  const blocks = [];
   477→  const priceRe = /(?:AU\$|USD?\$|\$|€|£|¥)\s?\d[\d,]*(?:\.\d{2})?/gi;
   478→
   479→  // Check sections, articles, divs with class hints
   480→  const selectors = [
   481→    "section",
   482→    "article",
   483→    '[class*="product"]',
   484→    '[class*="card"]',
   485→    '[class*="price"]',
   486→    '[class*="item"]',
   487→  ];
   488→
   489→  const seen = new Set();
   490→
   491→  selectors.forEach((sel) => {
   492→    $(sel).each((_, el) => {
   493→      const text = $(el).text().trim().replace(/\s+/g, " ");
   494→      if (!text || seen.has(text.slice(0, 80))) return;
   495→
   496→      const priceMatches = text.match(priceRe);
   497→      if (!priceMatches) return;
   498→
   499→      seen.add(text.slice(0, 80));
   500→
   501→      // Grab any image inside the block
   502→      const imgEl = $(el).find("img[src]").first();
   503→      const imgSrc = imgEl.length
   504→        ? safeAbsolute(imgEl.attr("src"), baseUrl)
   505→        : null;
   506→
   507→      // Grab heading inside block
   508→      const heading = $(el).find("h1,h2,h3,h4,h5").first().text().trim();
   509→
   510→      blocks.push({
   511→        heading: heading || "",
   512→        prices: [...new Set(priceMatches)],
   513→        image: imgSrc,
   514→        snippet: text.slice(0, 400),
   515→      });
   516→    });
   517→  });
   518→
   519→  return blocks.slice(0, 30); // cap for demo
   520→}
   521→
   522→// ---------------------------------------------------------------------------
   523→// CSS background-image sweep across all stylesheets
   524→// ---------------------------------------------------------------------------
   525→
   526→async function extractCssBgImages($, baseUrl) {
   527→  const images = [];
   528→  const cssJobs = [];
   529→
   530→  $('link[rel~="stylesheet"][href]').each((_, el) => {
   531→    const href = $(el).attr("href");
   532→    const abs = safeAbsolute(href, baseUrl);
   533→    if (abs) cssJobs.push(abs);
   534→  });
   535→
   536→  $("style").each((_, el) => {
   537→    cssJobs.push({ inline: true, css: $(el).text() });
   538→  });
   539→
   540→  const resolved = await Promise.all(
   541→    cssJobs.slice(0, 6).map(async (job) => {
   542→      if (job?.inline) return { css: job.css, base: baseUrl };
   543→      const { css, finalUrl } = await fetchCss(job);
   544→      return { css, base: finalUrl };
   545→    })
   546→  );
   547→
   548→  for (const { css, base } of resolved) {
   549→    extractBgImages(css, base).forEach((url) =>
   550→      images.push({ src: url, alt: "", source: "css-background" })
   551→    );
   552→  }
   553→
   554→  return images;
   555→}
