   557→// ---------------------------------------------------------------------------
   558→// Main entry point
   559→// ---------------------------------------------------------------------------
   560→
   561→/**
   562→ * Scrape a URL and return a structured result object.
   563→ *
   564→ * @param {string} url       - Target URL
   565→ * @param {boolean} useApi   - true = use ScraperAPI, false = direct fetch
   566→ * @returns {Promise<object>}
   567→ */
   568→export async function scrapeUrl(url, useApi = false) {
   569→  const html = useApi ? await fetchViaScraperApi(url) : await fetchDirect(url);
   570→
   571→  const $ = cheerio.load(html);
   572→  const title = $("title").text().trim().replace(/\s+/g, " ");
   573→  const description =
   574→    $('meta[name="description"]').attr("content") ||
   575→    $('meta[property="og:description"]').attr("content") ||
   576→    "";
   577→
   578→  // Run extractions (fonts + CSS bg images involve async network calls)
   579→  const [fonts, cssBgImages] = await Promise.all([
   580→    extractFonts($, url),
   581→    extractCssBgImages($, url),
   582→  ]);
   583→
   584→  const imgsDirect = extractImages(html, $, url);
   585→  const allImages = dedupeBy([...imgsDirect, ...cssBgImages], "src");
   586→
   587→  const { internal: internalLinks, external: externalLinks } = extractLinks(
   588→    $,
   589→    url
   590→  );
   591→  const files = extractFiles($, url);
   592→  const headings = extractHeadings($);
   593→  const productBlocks = extractProductBlocks($, url);
   594→
   595→  return {
   596→    meta: {
   597→      url,
   598→      title,
   599→      description,
   600→      scrapedAt: new Date().toISOString(),
   601→      mode: useApi ? "scraperapi" : "direct",
   602→    },
   603→    summary: {
   604→      images: allImages.length,
   605→      fonts: fonts.length,
   606→      files: files.length,
   607→      internalLinks: internalLinks.length,
   608→      externalLinks: externalLinks.length,
   609→      productBlocks: productBlocks.length,
   610→      headings: headings.length,
   611→    },
   612→    images: allImages,
   613→    fonts,
   614→    files,
   615→    links: { internal: internalLinks, external: externalLinks },
   616→    headings,
   617→    productBlocks,
   618→  };
   619→}
   620→
   621→/**
   622→ * Multi-page crawl: start at rootUrl, follow internal links that match
   623→ * pathFilter, up to maxPages pages.
   624→ *
   625→ * @param {string}   rootUrl    - Starting URL
   626→ * @param {RegExp}   pathFilter - Only follow links whose pathname matches
   627→ * @param {number}   maxPages   - Maximum pages to visit
   628→ * @param {boolean}  useApi
   629→ */
   630→export async function crawl(
   631→  rootUrl,
   632→  pathFilter = /.*/,
   633→  maxPages = 10,
   634→  useApi = false
   635→) {
   636→  const queue = [rootUrl];
   637→  const visited = new Set();
   638→  const results = [];
   639→
   640→  while (queue.length > 0 && visited.size < maxPages) {
   641→    const url = queue.shift();
   642→    if (visited.has(url)) continue;
   643→    visited.add(url);
   644→
   645→    console.log(`[crawl] Scraping (${visited.size}/${maxPages}): ${url}`);
   646→
   647→    try {
   648→      const data = await scrapeUrl(url, useApi);
   649→      results.push(data);
   650→
   651→      // Enqueue matching internal links not yet visited
   652→      for (const link of data.links.internal) {
   653→        if (!visited.has(link.href) && !queue.includes(link.href)) {
   654→          try {
   655→            const pathname = new URL(link.href).pathname;
   656→            if (pathFilter.test(pathname)) queue.push(link.href);
   657→          } catch {
   658→            // skip malformed
   659→          }
   660→        }
   661→      }
   662→    } catch (err) {
   663→      console.error(`[crawl] Failed ${url}: ${err.message}`);
   664→      results.push({ error: err.message, url });
   665→    }
   666→
   667→    // Polite delay between pages
   668→    if (queue.length > 0) await sleep(800);
   669→  }
   670→
   671→  return results;
   672→}
   673→
   674→function sleep(ms) {
   675→  return new Promise((r) => setTimeout(r, ms));
   676→}
