   726→</head>
   727→<body>
   728→
   729→<!-- Masthead -->
   730→<header class="masthead">
   731→  <div class="wordmark">
   732→    <div class="wordmark-dot"></div>
   733→    extract
   734→  </div>
   735→  <div class="masthead-meta">
   736→    <span class="spin" id="spinner"></span>
   737→    <div class="status-pill">
   738→      <div class="s-dot" id="s-dot"></div>
   739→      <span id="s-text">ready</span>
   740→    </div>
   741→  </div>
   742→</header>
   743→
   744→<!-- Query bar -->
   745→<div class="query-bar">
   746→  <div class="query-row">
   747→    <span class="q-label">URL</span>
   748→    <input class="url-input" type="url" id="url-input"
   749→      placeholder="paste any url…"
   750→      autocomplete="off" spellcheck="false" />
   751→    <button class="btn-run" id="scrape-btn" onclick="doScrape()">Scrape</button>
   752→    <button class="btn-crawl" id="crawl-btn" onclick="doCrawl()">Crawl</button>
   753→  </div>
   754→  <div class="query-opts">
   755→    <label class="qopt" title="Use ScraperAPI for JS-rendered pages (requires SCRAPERAPI_KEY)">
   756→      <input type="checkbox" id="use-api" /> scraperapi
   757→    </label>
   758→    <label class="qopt">
   759→      depth&nbsp;<input type="number" class="qopt-input" id="max-pages" value="5" min="1" max="20" />
   760→    </label>
   761→    <label class="qopt">
   762→      filter&nbsp;<input type="text" class="qopt-input wide" id="path-filter" value=".*" />
   763→    </label>
   764→  </div>
   765→</div>
   766→
   767→<!-- Page meta -->
   768→<div id="page-meta"></div>
   769→
   770→<!-- Stats -->
   771→<div id="summary">
   772→  <div class="stats-row">
   773→    <div class="stat" onclick="switchTabByName('images')">
   774→      <div class="stat-n" id="stat-images">0</div>
   775→      <div class="stat-l">Images</div>
   776→    </div>
   777→    <div class="stat" onclick="switchTabByName('fonts')">
   778→      <div class="stat-n" id="stat-fonts">0</div>
   779→      <div class="stat-l">Fonts</div>
   780→    </div>
   781→    <div class="stat" onclick="switchTabByName('files')">
   782→      <div class="stat-n" id="stat-files">0</div>
   783→      <div class="stat-l">Files</div>
   784→    </div>
   785→    <div class="stat" onclick="switchTabByName('links')">
   786→      <div class="stat-n" id="stat-links">0</div>
   787→      <div class="stat-l">Links</div>
   788→    </div>
   789→    <div class="stat" onclick="switchTabByName('products')">
   790→      <div class="stat-n" id="stat-products">0</div>
   791→      <div class="stat-l">Products</div>
   792→    </div>
   793→    <div class="stat" onclick="switchTabByName('headings')">
   794→      <div class="stat-n" id="stat-headings">0</div>
   795→      <div class="stat-l">Headings</div>
   796→    </div>
   797→  </div>
   798→</div>
   799→
   800→<!-- Results -->
   801→<div id="results">
   802→  <div class="layout">
   803→
   804→    <!-- Sidebar nav -->
   805→    <nav class="sidebar">
   806→      <div class="nav-label">Extracted</div>
   807→      <button class="nav-btn active" id="tab-btn-images" onclick="switchTab('images',this)">
   808→        Images <span class="nav-n" id="img-count">0</span>
   809→      </button>
   810→      <button class="nav-btn" id="tab-btn-fonts" onclick="switchTab('fonts',this)">
   811→        Fonts <span class="nav-n" id="font-count">0</span>
