   928→<script>
   929→let lastResult = null;
   930→let lastCrawlResult = null;
   931→
   932→// ── Tabs ──────────────────────────────────────────
   933→function switchTab(name, btn) {
   934→  document.querySelectorAll('.tab-panel').forEach(p => p.classList.remove('active'));
   935→  document.querySelectorAll('.nav-btn').forEach(b => b.classList.remove('active'));
   936→  document.getElementById('tab-' + name).classList.add('active');
   937→  if (btn) btn.classList.add('active');
   938→}
   939→function switchTabByName(name) {
   940→  switchTab(name, document.getElementById('tab-btn-' + name));
   941→}
   942→
   943→// ── Status ──────────────────────────────────────────
   944→function setStatus(msg, type = '') {
   945→  document.getElementById('s-text').textContent = msg;
   946→  document.getElementById('s-dot').className = 's-dot ' + type;
   947→  document.getElementById('spinner').style.display = type === 'loading' ? 'inline-block' : 'none';
   948→}
   949→function setLoading(msg) { setStatus(msg, 'loading'); }
   950→function setError(msg)   { setStatus('error: ' + msg, 'error'); }
   951→function setOk(msg)      { setStatus(msg, 'ok'); }
   952→
   953→function setBusy(busy) {
   954→  document.getElementById('scrape-btn').disabled = busy;
   955→  document.getElementById('crawl-btn').disabled  = busy;
   956→}
   957→
   958→// ── Scrape ──────────────────────────────────────────
   959→async function doScrape() {
   960→  const url    = document.getElementById('url-input').value.trim();
   961→  const useApi = document.getElementById('use-api').checked;
   962→  if (!url) { setError('enter a url'); return; }
   963→  setLoading('scraping…');
   964→  setBusy(true);
   965→  clearResults();
   966→  try {
   967→    const res  = await fetch('/api/scrape', {
   968→      method: 'POST',
   969→      headers: { 'Content-Type': 'application/json' },
   970→      body: JSON.stringify({ url, useApi }),
   971→    });
   972→    const data = await res.json();
   973→    if (!res.ok) throw new Error(data.error + (data.tip ? ' — ' + data.tip : ''));
   974→    lastResult = data;
   975→    renderResult(data);
   976→    setOk(`${data.summary.images} images · ${data.summary.fonts} fonts · ${data.summary.files} files`);
   977→  } catch (e) {
   978→    setError(e.message);
   979→  } finally {
   980→    setBusy(false);
   981→  }
   982→}
   983→
   984→// ── Crawl ──────────────────────────────────────────
   985→async function doCrawl() {
   986→  const url        = document.getElementById('url-input').value.trim();
   987→  const maxPages   = parseInt(document.getElementById('max-pages').value) || 5;
   988→  const pathFilter = document.getElementById('path-filter').value || '.*';
   989→  const useApi     = document.getElementById('use-api').checked;
   990→  if (!url) { setError('enter a url'); return; }
   991→  setLoading(`crawling up to ${maxPages} pages…`);
   992→  setBusy(true);
   993→  clearResults();
   994→  try {
   995→    const res  = await fetch('/api/crawl', {
   996→      method: 'POST',
   997→      headers: { 'Content-Type': 'application/json' },
   998→      body: JSON.stringify({ url, pathFilter, maxPages, useApi }),
   999→    });
  1000→    const data = await res.json();
  1001→    if (!res.ok) throw new Error(data.error);
  1002→    lastCrawlResult = data;
  1003→    renderCrawlResults(data);
  1004→    setOk(`crawled ${data.pages} pages`);
  1005→  } catch (e) {
  1006→    setError(e.message);
  1007→  } finally {
  1008→    setBusy(false);
  1009→  }
  1010→}
  1011→
  1012→document.getElementById('url-input').addEventListener('keydown', e => {
  1013→  if (e.key === 'Enter') doScrape();
  1014→});
  1015→
  1016→// ── Clear ──────────────────────────────────────────
  1017→function clearResults() {
  1018→  document.getElementById('results').style.display = 'none';
  1019→  document.getElementById('crawl-container').style.display = 'none';
  1020→  document.getElementById('summary').style.display = 'none';
  1021→  document.getElementById('page-meta').style.display = 'none';
  1022→  lastResult = lastCrawlResult = null;
  1023→}
  1024→
  1025→// ── Render ──────────────────────────────────────────
  1026→function renderResult(data) {
  1027→  document.getElementById('crawl-container').style.display = 'none';
  1028→
  1029→  const m = document.getElementById('page-meta');
  1030→  m.style.display = 'block';
  1031→  m.innerHTML = `
  1032→    <div class="meta-title">${esc(data.meta.title || '(no title)')}</div>
  1033→    ${data.meta.description ? `<div class="meta-desc">${esc(data.meta.description.slice(0,160))}</div>` : ''}
  1034→    <div class="meta-sub">${esc(data.meta.url)} · ${data.meta.mode} · ${new Date(data.meta.scrapedAt).toLocaleTimeString()}</div>
  1035→  `;
  1036→
  1037→  const s = data.summary;
  1038→  document.getElementById('stat-images').textContent   = s.images;
  1039→  document.getElementById('stat-fonts').textContent    = s.fonts;
  1040→  document.getElementById('stat-files').textContent    = s.files;
  1041→  document.getElementById('stat-links').textContent    = s.internalLinks + s.externalLinks;
  1042→  document.getElementById('stat-products').textContent = s.productBlocks;
  1043→  document.getElementById('stat-headings').textContent = s.headings;
  1044→  document.getElementById('summary').style.display = 'block';
  1045→
  1046→  document.getElementById('results').style.display = 'block';
  1047→  switchTabByName('images');
  1048→
  1049→  renderImages(data.images);
  1050→  renderFonts(data.fonts);
  1051→  renderFiles(data.files);
  1052→  renderLinks(data.links);
  1053→  renderProducts(data.productBlocks);
  1054→  renderHeadings(data.headings);
  1055→  renderJson(data);
  1056→}
  1057→
  1058→// ── Images ──────────────────────────────────────────
  1059→function renderImages(images) {
  1060→  const n = images.length;
  1061→  document.getElementById('img-count').textContent     = n;
  1062→  document.getElementById('img-count-sub').textContent = n + ' found';
  1063→  const el = document.getElementById('image-grid');
  1064→  if (!n) { el.innerHTML = empty('no images found'); return; }
  1065→  el.innerHTML = images.map(img => `
  1066→    <div class="img-cell">
  1067→      <img src="${esc(img.src)}" alt="${esc(img.alt)}"
  1068→        onerror="this.style.display='none';this.nextElementSibling.style.display='flex'" loading="lazy"/>
  1069→      <div class="img-err">☐</div>
  1070→      <div class="img-overlay">
  1071→        <span class="img-name">${esc(fileName(img.src))}</span>
  1072→        <a class="img-dl" href="/api/download?url=${enc(img.src)}&filename=${enc(fileName(img.src))}" download>↓</a>
  1073→      </div>
  1074→    </div>
  1075→  `).join('');
  1076→}
  1077→
  1078→// ── Fonts ──────────────────────────────────────────
  1079→function renderFonts(fonts) {
  1080→  const n = fonts.length;
