  1084→  if (!n) { el.innerHTML = empty('no @font-face fonts found'); return; }
  1085→  el.innerHTML = fonts.map(f => `
  1086→    <div class="font-row">
  1087→      <div class="font-preview" style="font-family:'${esc(f.family)}',sans-serif;">Aa</div>
  1088→      <div class="font-info">
  1089→        <div class="font-name">${esc(f.family)}</div>
  1090→        <div class="font-meta">weight ${esc(f.weight)} · ${esc(f.style)}</div>
  1091→      </div>
  1092→      <div style="display:flex;gap:4px;flex-wrap:wrap;align-items:center;">
  1093→        ${f.sources.map(s => `<span class="tag">${s.format}</span>`).join('')}
  1094→      </div>
  1095→      <a class="btn-dl"
  1096→        href="/api/download?url=${enc(f.downloadUrl)}&filename=${enc(f.family+'-'+f.weight+'.'+f.format)}" download>
  1097→        ↓ ${f.format.toUpperCase()}
  1098→      </a>
  1099→    </div>
  1100→  `).join('');
  1101→}
  1102→
  1103→// ── Files ──────────────────────────────────────────
  1104→function renderFiles(files) {
  1105→  const n = files.length;
  1106→  document.getElementById('file-count').textContent     = n;
  1107→  document.getElementById('file-count-sub').textContent = n + ' found';
  1108→  const el = document.getElementById('file-list');
  1109→  if (!n) { el.innerHTML = empty('no downloadable files found'); return; }
  1110→  el.innerHTML = files.map(f => `
  1111→    <div class="file-row">
  1112→      <div class="file-type ${fileIconClass(f.ext)}">${esc(f.type)}</div>
  1113→      <div class="file-info">
  1114→        <div class="file-name">${esc(f.text.slice(0,80))}</div>
  1115→        <div class="file-path">${esc(fileName(f.url))}</div>
  1116→      </div>
  1117→      <a class="btn-dl"
  1118→        href="/api/download?url=${enc(f.url)}&filename=${enc(fileName(f.url))}" download>↓</a>
  1119→    </div>
  1120→  `).join('');
  1121→}
  1122→
  1123→// ── Links ──────────────────────────────────────────
  1124→function renderLinks({ internal, external }) {
  1125→  const n = internal.length + external.length;
  1126→  document.getElementById('link-count').textContent     = n;
  1127→  document.getElementById('link-count-sub').textContent = n + ' found';
  1128→  document.getElementById('link-list').innerHTML     = internal.length  ? internal.map(linkRow).join('')  : empty('no internal links');
  1129→  document.getElementById('ext-link-list').innerHTML = external.length ? external.map(linkRow).join('') : empty('no external links');
  1130→}
  1131→function linkRow(l) {
  1132→  return `
  1133→    <div class="link-row">
  1134→      <span class="link-text" title="${esc(l.text)}">${esc(l.text || '(no text)')}</span>
  1135→      <span class="link-href">${esc(l.href)}</span>
  1136→      <a class="link-ext" href="${esc(l.href)}" target="_blank" rel="noopener" title="Open">↗</a>
  1137→    </div>`;
  1138→}
  1139→
  1140→// ── Products ──────────────────────────────────────────
  1141→function renderProducts(blocks) {
  1142→  const n = blocks.length;
  1143→  document.getElementById('product-count').textContent     = n;
  1144→  document.getElementById('product-count-sub').textContent = n + ' found';
  1145→  const el = document.getElementById('product-grid');
  1146→  if (!n) { el.innerHTML = `<div style="padding:20px;">${empty('no pricing blocks found')}</div>`; return; }
  1147→  el.innerHTML = blocks.map(b => `
  1148→    <div class="product-cell">
  1149→      ${b.image ? `<img class="product-img" src="${esc(b.image)}" alt="" onerror="this.style.display='none'" loading="lazy"/>` : ''}
  1150→      ${b.heading ? `<div class="product-title">${esc(b.heading)}</div>` : ''}
  1151→      <div class="price-list">${b.prices.map(p => `<span class="price-item">${esc(p)}</span>`).join('')}</div>
  1152→      <div class="product-snip">${esc(b.snippet)}</div>
  1153→    </div>
  1154→  `).join('');
  1155→}
  1156→
  1157→// ── Headings ──────────────────────────────────────────
  1158→function renderHeadings(headings) {
  1159→  const n = headings.length;
  1160→  document.getElementById('heading-count').textContent     = n;
  1161→  document.getElementById('heading-count-sub').textContent = n + ' found';
  1162→  const el = document.getElementById('heading-list');
  1163→  if (!n) { el.innerHTML = empty('no headings found'); return; }
  1164→  el.innerHTML = headings.map(h => `
  1165→    <div class="heading-row">
