  1171→
  1172→// ── JSON ──────────────────────────────────────────
  1173→function renderJson(data) {
  1174→  document.getElementById('json-output').innerHTML = syntaxHighlight(JSON.stringify(data, null, 2));
  1175→}
  1176→function downloadJson() {
  1177→  if (!lastResult) return;
  1178→  triggerDownload(JSON.stringify(lastResult, null, 2), 'scraper-result.json', 'application/json');
  1179→}
  1180→
  1181→// ── Crawl results ──────────────────────────────────────────
  1182→function renderCrawlResults(data) {
  1183→  document.getElementById('results').style.display = 'none';
  1184→  document.getElementById('summary').style.display = 'none';
  1185→  document.getElementById('crawl-container').style.display = 'block';
  1186→  document.getElementById('crawl-list').innerHTML = data.results.map((r, i) => {
  1187→    if (r.error) return `
  1188→      <div class="crawl-row" style="cursor:default;">
  1189→        <span class="crawl-row-title" style="color:var(--red)">Error — ${esc(r.url)}</span>
  1190→        <span class="chip">${esc(r.error)}</span>
  1191→      </div>`;
  1192→    const s = r.summary;
  1193→    return `
  1194→      <div class="crawl-row" onclick="openCrawlPage(${i})">
  1195→        <span class="crawl-row-title">${esc(r.meta.title || '(no title)')}</span>
  1196→        <span class="crawl-row-url">${esc(r.meta.url)}</span>
  1197→        <div class="crawl-chips">
  1198→          <span class="chip">${s.images} img</span>
  1199→          <span class="chip">${s.fonts} font</span>
  1200→          <span class="chip">${s.files} file</span>
  1201→          <span class="chip">${s.internalLinks} link</span>
  1202→        </div>
  1203→      </div>`;
  1204→  }).join('');
  1205→}
  1206→
  1207→function openCrawlPage(i) {
  1208→  if (!lastCrawlResult) return;
  1209→  const page = lastCrawlResult.results[i];
  1210→  lastResult = page;
  1211→  document.getElementById('crawl-container').style.display = 'none';
  1212→  renderResult(page);
  1213→  setOk('showing: ' + page.meta.url);
  1214→}
  1215→function downloadCrawlJson() {
  1216→  if (!lastCrawlResult) return;
  1217→  triggerDownload(JSON.stringify(lastCrawlResult, null, 2), 'crawl-results.json', 'application/json');
  1218→}
  1219→
  1220→// ── Utils ──────────────────────────────────────────
  1221→function esc(s) {
  1222→  if (s == null) return '';
  1223→  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  1224→}
  1225→function enc(s) { return encodeURIComponent(s || ''); }
  1226→function fileName(url) {
  1227→  try { return decodeURIComponent(new URL(url).pathname.split('/').pop()) || url; }
  1228→  catch { return url; }
  1229→}
  1230→function fileIconClass(ext) {
  1231→  if (ext === 'pdf') return 'pdf';
  1232→  if (['zip','gz','tar','rar','7z'].includes(ext)) return 'zip';
  1233→  if (['doc','docx'].includes(ext)) return 'doc';
  1234→  if (['xls','xlsx','csv'].includes(ext)) return 'xlsx';
  1235→  return 'other';
  1236→}
  1237→function empty(msg) {
  1238→  return `<div class="empty"><div class="empty-n">—</div><div class="empty-msg">${esc(msg)}</div></div>`;
  1239→}
  1240→function triggerDownload(content, filename, type) {
  1241→  const blob = new Blob([content], { type });
  1242→  const a = Object.assign(document.createElement('a'), { href: URL.createObjectURL(blob), download: filename });
  1243→  a.click();
  1244→  URL.revokeObjectURL(a.href);
  1245→}
  1246→function syntaxHighlight(json) {
  1247→  return json.replace(
  1248→    /("(\\u[a-zA-Z0-9]{4}|\\[^u]|[^\\"])*"(\s*:)?|\b(true|false|null)\b|-?\d+(?:\.\d*)?(?:[eE][+\-]?\d+)?)/g,
  1249→    m => {
  1250→      let c = 'json-num';
  1251→      if (/^"/.test(m)) c = /:$/.test(m) ? 'json-key' : 'json-str';
  1252→      else if (/true|false/.test(m)) c = 'json-bool';
  1253→      else if (/null/.test(m)) c = 'json-null';
  1254→      return `<span class="${c}">${m}</span>`;
  1255→    }
  1256→  );
  1257→}
  1258→</script>
